    if (me->query("family/master_id") != query("id"))
        return "只有我的弟子才配使用这玄铁棋盘。";

    if (me->query_skill("fenglei-panfa", 1) < 150)
        return "你还是下去将你的风雷盘法练练再来吧。";

    if (me->query_skill("chess", 1) < 100)
        return "你连奕棋都不会，用我这宝贝干嘛？";

    if (present("xuantie qipan", me))
        return "现在玄铁棋盘不就在你身上吗，怎么老是跟我纠缠不休？";

    ob = present("xuantie qipan", this_object());

    if (!objectp(ob))
        return "现在玄铁棋盘已经不在我这里了。";

    ob->move(this_object());
    command("give xuantie qipan to " + me->query("id"));

    ob = new("/d/items/hammer/tieqipan");
    ob->move(this_object());
    ob->wield();

    return "很好，既然这样，我这玄铁棋盘你就暂时拿去用吧。";
}

mixed ask_riyue() {
    object me;

    me = this_player();

    if (me->query("family/family_name") != "日月神教") {
        command("say 本庄只接待神教人士！");
        return 1;
    }

    if (me->query("can_learn/meizhuang")) {
        command("say 你不是已经会了吗？还来找我干什么！");
        return 1;
    }

    command("say 恩，那好吧，我就教你风雷盘法。");

    me->set_skill("fenglei-panfa", 10);
    me->set("can_learn/meizhuang", 1);

    if (me->query("gongxian") > 10000 &&
        me->query("balance") > 100000000) {
        me->add("gongxian", -10000);
        me->add("balance", -100000000);
        me->set("can_perform/fenglei-panfa/fenglei", 1);
    }

    tell_object(me, HIG "你学会了风雷盘法！\n" NOR);

    command("say 下去好好练习吧。");

    return 1;

}

int accept_object(object me, object ob) {
    int r;
    if (r = ::accept_object(me, ob))
        return r;

    if (base_name(ob) != QIPAN) {
        command("say 你给我这种东西干什么？");
        return 0;
    }

    if (me->query("family/master_id") != query("id"))
        command("say 多谢这位" + RANK_D->query_respect(me) +
            "将我的宝贝交回。");
    else
        command("say 很好，很好！");
    destruct(ob);
    return 1;
}

void unconcious() {
    die();
}

